Dear jax team,
after recent improvements to linalg.solve (thanks again!) I found that it has some issues with being autodiff'ed. I have not yet digged into the error messages, but they rather sound like a minute error in handling the shapes than some fundamental limitation.
import jax
import jax.numpy as np
import numpy as onp

@jax.jit
def solve(A, b):
    return np.linalg.solve(A, b)

def to_gpu(arr):
    return jax.device_put(arr.astype(onp.float32))

A = to_gpu(onp.random.rand(100, 3, 3))
b = to_gpu(onp.random.rand(100, 3))

x = solve(A, b)
assert onp.allclose(jax.vmap(np.dot)(A, x), b, atol=1e-4, rtol=1e-4)

print("# BATCHED")
try:
    jac0 = jax.jacobian(solve, argnums=0)(A, b)  # error
except Exception as e: 
    print(e) 
# triangular_solve requires both arguments to have the same number of dimensions and equal batch dimensions, got (100, 3, 3) and (100, 100, 3, 3)

try:
    jac1 = jax.jacobian(solve, argnums=1)(A, b)  # error
except Exception as e:
    print(e)
# 'Zero' object is not subscriptable

print("# SINGLE")
try:
    jac0 = jax.jacobian(solve, argnums=0)(A[0], b[0])  # fine
except Exception as e:
    print(e)

try:
    jac1 = jax.jacobian(solve, argnums=1)(A[0], b[0])  # error
except Exception as e:
    print(e)
# 'Zero' object is not subscriptable

Hi! I want to define custom gradients for a simulation for sensitivity analysis. I have been using autograd for this, but since it is not actively being developed anymore I wanted to switch to jax.
In autograd I would write something like this:
from autograd import grad
from autograd.extend import primitive, defvjp
import simulation

@primitive
def sim(params):
    results = simulation.run(params)
    return results

def sim_vjp(ans, params):
    def vjp(g):
        # custom gradient code goes here
        return gradient
    return vjp

defvjp(sim, sim_vjp)
In autograd, this worked fine and I was able to chain this together with some other differentiable transformations and get gradients out of the whole thing.
From what I was able to gather, the above would be written in jax as follows:
import jax
import simulation

@jax.custom_transforms
def sim(params):
    results = simulation.run(params)
    return results

def sim_vjp(ans, params):
    def vjp(g):
        # custom gradient code goes here
        return gradient
    return vjp

jax.defvjp_all(sim, sim_vjp)
However, this throws Exception: Tracer can't be used with raw numpy functions., which I assume is because the simulation code does not use jax. Are the custom gradients in jax not black-boxes as in autograd anymore, i.e. is this a fundamental limitation or have I screwed something up? Do I need to implement this using lax primitives, and if so, how?
I would be grateful for a minimal example implementing this for some arbitrary non-jax function. This code here for example works in autograd:
from autograd import grad
from autograd.extend import primitive, defvjp
from scipy.ndimage import gaussian_filter

@primitive
def filter(img):
    return gaussian_filter(img, 1)

def filter_vjp(ans, img):
    def vjp(g):
        return gaussian_filter(g, 1)
    return vjp

defvjp(filter, filter_vjp)
How would one translate this so it works in jax?
Thanks so much!

I would like to write functions that take static options (associated with branching within the function) that are compatible with both vmap and jit. Some examples of things that currently work/don't work:
def python_control_flow(x, option=False):
  return x**2 if option else x**3

vmap(python_control_flow)(np.arange(3))  # works
vmap(jit(python_control_flow))(np.arange(3))  # works
(lambda x: jit(python_control_flow)(x, True))(np.arange(3))  # doesn't work
vmap(jit(lambda x: python_control_flow(x, True)))(np.arange(3))  # works
vmap(python_control_flow, in_axes=(0, None))(np.arange(3), True)  # doesn't work

def cond_control_flow(x, option=False):
  return lax.cond(option, x, lambda x: x**2, x, lambda x: x**3)

cond_control_flow(np.arange(3))  # works
jit(cond_control_flow)(np.arange(3))  # doesn't work, https://github.com/google/jax/issues/1077
vmap(cond_control_flow)(np.arange(3))  # doesn't work
vmap(jit(cond_control_flow))(np.arange(3))  # doesn't work
vmap(cond_control_flow, in_axes=(0, None))(np.arange(3), True)  # doesn't work
It seems that for the best compatibility with jit the lax.cond control flow is preferable, perhaps with a wrapper, e.g.,
@jit
def _cond_control_flow(x, option):
  return lax.cond(option, x, lambda x: x**2, x, lambda x: x**3)

def cond_control_flow(x, option=False):
  return _cond_control_flow(x, option)
to avoid #1077, but no approach along these lines is currently compatible with a vmap down the line due to NotImplementedError: Batching rule for 'cond' not implemented.

import jax.numpy as np
from jax import grad, jit
from jax.lax import scan

f = lambda carry, _: ({k : v+carry['a'] for k,v in carry.items()}, np.zeros(()))

# this works
def loss(param):
  init_carry = {'a': param, 'b': np.zeros(())}
  final_carry, ys = scan(f, init_carry, np.array([1,2]))
  return final_carry['a'] * param
test = grad(loss)(np.zeros(()))

# this works
@jit
def loss(param):
  init_carry = {'a': param, 'b': np.zeros(())}
  final_carry, ys = scan(f, init_carry, np.array([1,2]))
  return final_carry['a'] * param
test = loss(np.zeros(()))

# this works
@jit
def loss(param):
  init_carry = {'a': param, 'b': np.zeros(())}
  final_carry, ys = scan(f, init_carry, np.array([1,2]))
  return final_carry['a'] * param + 0. * final_carry['b']
test = grad(loss)(np.zeros(()))

# this doesn't work
@jit
def loss(param):
  init_carry = {'a': param, 'b': np.zeros(())}
  final_carry, ys = scan(f, init_carry, np.array([1,2]))
  return final_carry['a'] * param
test = grad(loss)(np.zeros(()))

